def get_act_fn(name: str) -> Callable:
    _ACT_FNS = [
        "linear", "tanh", "hard_tanh", "relu", "leaky_relu", "gelu", "selu", "silu"
    ]
    if name == "linear":
        return nn.Identity()
    elif name == "tanh":
        return jnp.tanh
    elif name == "hard_tanh":
        return jax.nn.hard_tanh
    elif name == "relu":
        return jax.nn.relu
    elif name == "leaky_relu":
        return jax.nn.leaky_relu
    elif name == "gelu":
        return jax.nn.gelu
    elif name == "selu":
        return jax.nn.selu
    elif name == "silu":
        return jax.nn.silu
    else:
        raise ValueError(f"""
                Invalid activation function ID. Options are {_ACT_FNS}.
        """)
    

def simple_make_mlp(key: PRNGKeyArray, 
        input_dim: int, 
        width: int,
        depth: int, 
        output_dim: int, 
        act_fn: str, 
        use_layer_norm: bool = False,
        use_bias: bool = False,):
    subkeys = jax.random.split(key, depth + 1)
    layers = []
    for i in range(depth):
        # First layer: no activation, Last layer: no activation, Hidden layers: activation
        is_first = i == 0
        is_last = i == depth - 1
        act_fn_l = nn.Identity() if (is_first or is_last) else get_act_fn(act_fn)
        
        in_dim = input_dim if i == 0 else width
        out_dim = output_dim if i == depth - 1 else width

        linear = nn.Linear(in_dim, out_dim, use_bias=use_bias, key=subkeys[i])
        layers.append(eqx.nn.Sequential([
            nn.Lambda(act_fn_l), 
            linear, 
            nn.LayerNorm(out_dim) if use_layer_norm else nn.Identity()
        ]))

    return layers

# %% ../nbs/00_core.ipynb 6
class ResidualMLPLayer(eqx.Module):
    linear: nn.Linear
    ln_pre: eqx.Module
    ln_post: eqx.Module
    act: eqx.Module
    dropout: nn.Dropout
    ln_position: Literal["pre", "post"]
    use_residual: bool

    def __init__(
        self,
        key: PRNGKeyArray,
        in_dim: int,
        out_dim: int,
        act_module: eqx.Module,
        use_layer_norm: bool,
        use_bias: bool,
        ln_position: Literal["pre", "post"],
        dropout_rate: float = 0.0,
        use_residual: bool = True,
        init_method: Literal["kaiming", None] = None,
        init_gain: float = 1.0,
    ):
        self.linear = nn.Linear(in_dim, out_dim, use_bias=use_bias, key=key)
        self.act = act_module
        self.ln_position = ln_position

        # Residual check
        if use_residual and (in_dim == out_dim):
            self.use_residual = True
        elif use_residual and (in_dim != out_dim):
            raise ValueError(
                f"Residual connection requires in_dim == out_dim, "
                f"current in_dim: {in_dim}, out_dim: {out_dim}"
            )
        else:
            self.use_residual = False

        # LayerNorm modules
        if use_layer_norm:
            self.ln_pre = nn.LayerNorm(in_dim)
            self.ln_post = nn.LayerNorm(out_dim)
        else:
            self.ln_pre = nn.Identity()
            self.ln_post = nn.Identity()

        # Dropout module (no-op if rate == 0.0 at runtime)
        # Remember you must pass a key when calling this layer under jit.
        self.dropout = nn.Dropout(p=dropout_rate)

        if init_method == "kaiming":
            self.kaiming_init(key, gain=init_gain)

    def __call__(self, x, *, key: PRNGKeyArray | None = None, inference: bool = False):
        """
        x: input tensor
        key: PRNG key for dropout (required if dropout_rate > 0 and not inference)
        inference: if True, disables dropout
        """
        residual = x if self.use_residual else None

        if self.ln_position == "pre":
            h = self.ln_pre(x)
            h = self.linear(h)
            h = self.act(h)
        elif self.ln_position == "post":
            h = self.linear(x)
            h = self.act(h)
            h = self.ln_post(h)
        else:  # should not happen if type-checked
            raise ValueError(f"Invalid ln_position: {self.ln_position!r}")

        # Apply dropout after activation (and LN in post-LN case is already included above)
        # eqx.nn.Dropout expects key and inference flag at call time.
        h = self.dropout(h, key=key, inference=inference)

        if residual is not None:
            return residual + h
        else:
            return h
        
    def kaiming_init(self, key: PRNGKeyArray, gain: float = 1.0):
        """
        Reinitialize the linear layer's weight using Kaiming (He) initialization.
        
        Args:
            key: PRNG key for random initialization
            gain: scaling factor for the initialization (default 1.0)
        """
        # Kaiming initialization: scale = sqrt(1.0 / fan_in)
        in_features = self.linear.in_features
        scale = jnp.sqrt(1.0 / in_features)
        
        # Get the current weight shape and dtype
        w = self.linear.weight
        
        # Generate new weights with Kaiming initialization
        new_w = jax.random.normal(key, w.shape, dtype=w.dtype) * scale * gain
        
        # Update weight using eqx.tree_at
        self.linear = eqx.tree_at(lambda m: m.weight, self.linear, new_w)
        
        # Reset bias to zero if it exists
        if self.linear.use_bias:
            self.linear = eqx.tree_at(
                lambda m: m.bias, 
                self.linear, 
                jnp.zeros_like(self.linear.bias)
            )


class Simple_MLPlayer(eqx.Module):
    """Block: x -> Act -> Linear -> (optional) LayerNorm.

    This reproduces the original Sequential:
        [nn.Lambda(act_fn_l), linear, LayerNorm or Identity]
    """

    linear: nn.Linear
    ln: eqx.Module
    act: eqx.Module

    def __init__(
        self,
        key: PRNGKeyArray,
        in_dim: int,
        out_dim: int,
        act_module: eqx.Module,
        use_layer_norm: bool,
        use_bias: bool,
        init_method: Literal["kaiming", None] = None,
        init_gain: float = 1.0,
    ):
        self.linear = nn.Linear(in_dim, out_dim, use_bias=use_bias, key=key)
        self.act = act_module
        self.ln = nn.LayerNorm(out_dim) if use_layer_norm else nn.Identity()

        if init_method == "kaiming":
            self.kaiming_init(key, gain=init_gain)

    def __call__(
        self,
        x: jnp.ndarray,
        *,
        key: PRNGKeyArray | None = None,
        inference: bool = False,
    ) -> jnp.ndarray:
        # key and inference are accepted for API compatibility but ignored.
        x = self.act(x)      # nn.Lambda(act_fn_l)
        x = self.linear(x)   # Linear
        x = self.ln(x)       # LayerNorm(out_dim) or Identity
        return x
    
    def kaiming_init(self, key: PRNGKeyArray, gain: float = 1.0):
        """
        Reinitialize the linear layer's weight using Kaiming (He) initialization.
        
        Args:
            key: PRNG key for random initialization
            gain: scaling factor for the initialization (default 1.0)
        """
        # Kaiming initialization: scale = sqrt(1.0 / fan_in)
        in_features = self.linear.in_features
        scale = jnp.sqrt(1.0 / in_features)
        
        # Get the current weight shape and dtype
        w = self.linear.weight
        
        # Generate new weights with Kaiming initialization
        new_w = jax.random.normal(key, w.shape, dtype=w.dtype) * scale * gain
        
        # Update weight using eqx.tree_at
        self.linear = eqx.tree_at(lambda m: m.weight, self.linear, new_w)
        
        # Reset bias to zero if it exists
        if self.linear.use_bias:
            self.linear = eqx.tree_at(
                lambda m: m.bias, 
                self.linear, 
                jnp.zeros_like(self.linear.bias)
            )


def make_modern_mlp(
    key: PRNGKeyArray,
    input_dim: int,
    width: int,
    depth: int,
    output_dim: int,
    act_fn: str,
    use_layer_norm: bool = False,
    use_bias: bool = False,
    ln_position: Literal["pre", "post"] = "pre",
    dropout_rate: float = 0.0,
    use_residual_blocks: bool = False,
    init_method: Literal["kaiming", None] = None,
    init_gain: float = 1.0,
):
    """
    Build an MLP as a stack of blocks.

    If use_residual_blocks is True:
        ResidualMLPLayer is used for each layer.

        For each layer:
            - ln_position == "pre":
                x -> LN -> Linear -> Act -> Dropout -> (+ x if dims match)
            - ln_position == "post":
                x -> Linear -> Act -> LN -> Dropout -> (+ x if dims match)

        Residual connection is only applied when in_dim == out_dim for that layer.
        Here, the last layer uses no residual.

    If use_residual_blocks is False:
        Simple_MLPlayer is used for each layer:
            x -> Act -> Linear -> (optional) LayerNorm
        (no residual, no dropout).
    """
    subkeys = jax.random.split(key, depth)
    layers = []

    for i in range(depth):
        is_first = i == 0
        is_last = i == depth - 1

        in_dim = input_dim if is_first else width
        out_dim = output_dim if is_last else width

        # First and last layer: no activation, hidden layers: chosen activation
        act_module = nn.Identity() if (is_first or is_last) else get_act_fn(act_fn)

        if use_residual_blocks:
            layer = ResidualMLPLayer(
                key=subkeys[i],
                in_dim=in_dim,
                out_dim=out_dim,
                act_module=act_module,
                use_layer_norm=use_layer_norm,
                use_bias=use_bias,
                ln_position=ln_position,
                dropout_rate=dropout_rate,
                # last layer: no residual; others: residual (if dims match)
                use_residual=False if (is_last or is_first) else True,
                init_method=init_method,
                init_gain=init_gain,
            )
        else:
            layer = Simple_MLPlayer(
                key=subkeys[i],
                in_dim=in_dim,
                out_dim=out_dim,
                act_module=act_module,
                use_layer_norm=use_layer_norm,
                use_bias=use_bias,
            )

        layers.append(layer)

    return layers

