@eqx.filter_jit
def one_step_forward(model, x, key, *, inference: bool = False):
    keys = jax.random.split(key, len(model))
    for layer, k in zip(model, keys):
        # batched: x has shape [batch, feat]
        vlayer = eqx.filter_vmap(lambda x: layer(x, key=k, inference=inference), in_axes=0, out_axes=0)
        x = vlayer(x)
    return x

# %% ../nbs/00_core.ipynb 19
# Define loss function
def compute_ce_loss(model, x, y, key, inference: bool = False):
    logits = one_step_forward(model, x, key=key, inference=inference)
    # return optax.softmax_cross_entropy_with_integer_labels(logits, y).mean()
    return optax.softmax_cross_entropy(logits, y).mean()

def compute_mse_loss(model, x, y, key, inference: bool = False):
    logits = one_step_forward(model, x, key=key, inference=inference)
    
    return jnp.mean((logits - y) ** 2)


# Define update step
@eqx.filter_jit
def train_step(model, optimizer, opt_state, x, y, key, loss_fn = compute_ce_loss):
    loss, grads = eqx.filter_value_and_grad(loss_fn)(model, x, y, key=key, inference=False)
    updates, opt_state = optimizer.update(grads, opt_state, eqx.filter(model, eqx.is_array))
    model = eqx.apply_updates(model, updates)
    return {'model': model, 
            'opt_state': opt_state, 
            'loss': loss,
            'grads': grads
        }


def validate(model, data_loader, key, loss_fn = compute_ce_loss):
    total_loss = 0.0
    num_batches = 0
    preds = []
    ys = []
    for images, labels in data_loader:
        # Convert torch tensors to jax arrays
        x = jnp.array(images.numpy())
        y = jnp.array(labels.numpy())
        preds.append(one_step_forward(model, x, key=key, inference=True))
        ys.append(y)
        loss = loss_fn(model, x, y, key=key, inference=True)
        total_loss += loss
        num_batches += 1
    
    # compute accuracy
    acc = jnp.mean(jnp.concatenate(preds).argmax(axis=-1) == jnp.concatenate(ys).argmax(axis=-1))
    avg_loss = total_loss / num_batches
    return avg_loss, acc


