def forward_and_extract_activities(
    model: List, x, key, *, inference: bool = False
):
    """
    Apply a list of layers (ResidualMLPLayer or Simple_MLPlayer)
    to a batched input x and return the activations after each layer.

    Args:
        model: list of layers, each with __call__(x_single, *, key, inference).
        x: array of shape (batch, feat_in) for the first layer.
        key: PRNGKey for stochastic layers (dropout). One subkey per layer.
        inference: if True, disable dropout inside layers.

    Returns:
        activations: list of arrays; activations[i] is the output of layer i
                        with shape (batch, feat_i).
    """
    keys = jax.random.split(key, len(model))
    activations = []
    h = x

    for layer, k in zip(model, keys):
        # vmap over batch dimension
        vlayer = eqx.filter_vmap(lambda x_single: layer(x_single, key=k, inference=inference), in_axes=0, out_axes=0)
        h = vlayer(h)
        activations.append(h)

    return activations


