# %% ../nbs/00_core.ipynb 26
def jpc_init_activities_with_ffwd(
        model: PyTree[Callable],
        input: ArrayLike,
) -> PyTree[Array]:

    L = len(model)
    z1 = jax.vmap(model[0])(input)

    activities = [z1]
    for l in range(1, L):
        zl = jax.vmap(model[l])(activities[l - 1])
        activities.append(zl)
    return activities

# %% ../nbs/00_core.ipynb 34
def init_activities_from_normal_ffwd(
    key: PRNGKeyArray, 
    model: List[Callable], 
    input_shape: Tuple[int, ...],  # Just the shape, not actual data
    sigma: Scalar = 0.05,
    inference: bool = False,
    include_input: bool = True,  # include input for unsupervised inference or validation
) -> List[Array]:
    """Initialize activities by random."""
    batch_size, *input_dims = input_shape
    
    # Create random input
    random_input = sigma * jax.random.normal(key, input_shape)
    
    # Forward pass to get activity shapes
    activities_clean = forward_and_extract_activities(model, random_input, key=key, inference=inference)
    
    # Add noise to each activity
    random_keys = jax.random.split(key, len(activities_clean))
    random_activities = [
        sigma * jax.random.normal(k, act.shape)
        for act, k in zip(activities_clean, random_keys)
    ]
    if include_input:
        random_activities.insert(0, random_input)
    return random_activities

