def clip_array_by_row(energy_arr, max_norm=1.0, ord=None):
    '''
    To clip each row vector of energy_arr to have maximum norm of max_norm.
    '''
    row_norms = jnp.linalg.norm(energy_arr, axis=-1, ord=ord, keepdims=True) 
    scale_factors = jnp.minimum(1.0, max_norm / (row_norms + 1e-8))  
    return energy_arr * scale_factors  

# %% ../nbs/00_core.ipynb 41
def mse_energy(prev_acts, curr_acts):
    # 将在接下来的compute_energy中除以batch_size
    # 这样做的原因是不希望mean掉feature dimensions
    err = prev_acts - curr_acts
    return 0.5 * (jnp.mean(err ** 2, axis = -1)).sum()  


def cos_similar_energy(prev_acts, curr_acts):
    """
    Compute energy based on cosine similarity.
    Energy is higher when vectors are less similar.
    Returns: 1 - cosine_similarity, where 0 means perfect alignment.
    """
    # Normalize vectors
    prev_norm = prev_acts / (jnp.linalg.norm(prev_acts, axis=-1, keepdims=True) + 1e-8)
    curr_norm = curr_acts / (jnp.linalg.norm(curr_acts, axis=-1, keepdims=True) + 1e-8)
    
    # Compute cosine similarity
    cos_sim = (prev_norm * curr_norm).sum(axis=-1)
    
    # Convert to energy (1 - similarity, so dissimilarity)
    energy = (1 - jnp.abs(cos_sim)).sum()  # abs makes the opppsite direction also good, so this is a sort of disagreement
    
    return energy



def compute_energy(model: List[Callable], activations: List[ArrayLike], key: PRNGKeyArray, y: ArrayLike, x: ArrayLike = None, ener_fn: Callable = mse_energy, loss_fn: Callable = mse_energy, inference: bool = True) -> List[ArrayLike]:
    '''
    energy = (previous layer's activations - current layer's activations) ** 2
    '''
    energies = []
    key, layer0_key = jax.random.split(key)
    vlayer0 = eqx.filter_vmap(
        lambda x_single: model[0](x_single, key=layer0_key, inference=inference), 
        in_axes=0, out_axes=0
    )
    if x == None:
        if len(activations) == len(model) + 1:  # with input
            x, * activations = activations
        else:
            raise NotImplementedError("x must be provided")
    
    energies.append(ener_fn(activations[0], vlayer0(x)))  # (h1 - f(x)) ** 2
    for idx in range(1, len(model)-1):
        key, layer_key = jax.random.split(key)
        vlayer = eqx.filter_vmap(lambda x_single: model[idx](x_single, key=layer_key, inference=inference), in_axes=0, out_axes=0)
        energies.append(ener_fn(activations[idx], vlayer(activations[idx-1])))

    
    # energies.append(0.5 * ((y - activations[-1]) ** 2).sum())  # (y - f(h_last))
    # another way to compute output layer error
    key, last_key = jax.random.split(key)
    vlayer_last = eqx.filter_vmap(
        lambda x_single: model[-1](x_single, key=last_key, inference=inference), 
        in_axes=0, out_axes=0
    )

    if y == None:
        batch_size = x.shape[0]
        energies = [e / batch_size for e in energies]
        return energies
    else:
        # eL = y - vlayer_last(activations[-2])
        energies.append(loss_fn(vlayer_last(activations[-2]), y))  # (y - f(h_last))

        batch_size = y.shape[0]
        energies = [e / batch_size for e in energies]
        return energies


# %% ../nbs/00_core.ipynb 42
def jpc_pc_energy_fn(
        params: Tuple[PyTree[Callable], Optional[PyTree[Callable]]],
        activities: PyTree[ArrayLike],
        y: ArrayLike,
        x: Optional[ArrayLike] = None,
        record_layers: bool = False
) -> Scalar | Array:

    """
    WARNINIG: Cannot handle random activations for now
    """
    # if x is None:
    #     raise NotImplementedError("becau")
    model, skip_model = params

    # if x == None:
    #     if len(activations) == len(model) + 1:  # with input
    #         x, * activations = activations
    #     else:
    #         raise NotImplementedError("x must be provided")
        

    batch_size = y.shape[0]
    start_activity_l = 1 if x is not None else 2
    n_activity_layers = len(activities) - 1
    n_hidden = len(model) - 1


    eL = y - jax.vmap(model[-1])(activities[-2])
    energies = [0.5 * (eL ** 2).sum()]

    for act_l, net_l in zip(
            range(start_activity_l, n_activity_layers),
            range(1, n_hidden)
    ):
        err = activities[act_l] - jax.vmap(model[net_l])(activities[act_l - 1])
        energies.append(0.5 * (err ** 2).sum())


    if x is not None:
        e1 = activities[0] - jax.vmap(model[0])(x)
    else:
        e1 = activities[1] - jax.vmap(model[0])(activities[0])

    energies.append(0.5 * (e1 ** 2).sum())

    total_energy = jnp.array(energies).sum() / batch_size

    if record_layers:
        return jnp.array(energies) / batch_size
    else:
        return total_energy

