# Version 2. JIT friendly with jax.lax.fori_loop and history recording
def perform_inference(model: List[Callable], activations: List[Array], key, yy: ArrayLike, xx: ArrayLike = None, num_iters: int = 10, lr: float = 0.05, record_history: bool = False, ener_fn: Callable = mse_energy, loss_fn: Callable = mse_energy, inference: bool = True):
    '''
    Perform inference by minimizing energy.
    
    Args:
        record_history: If True, returns (final_activations, energy_history) where energy_history 
                    is an array of shape (num_iters+1, num_layers) containing energies at each iteration.
                    If False, only returns final_activations.
    '''
    # Extract activations by directly passing model layers (no wrapping needed)
    # activations = forward_and_extract_activites(model, x)
    
    def energy_fn(acts):
        return sum(compute_energy(model, acts, key, yy, xx, ener_fn=ener_fn, loss_fn=loss_fn, inference=inference))
    
    @eqx.filter_jit
    def inference_step(acts):
        new_energy, grads = jax.value_and_grad(energy_fn)(acts)
        return jax.tree.map(lambda a, g: a - lr * g, acts, grads)
    
    if record_history:
        # Preallocate energy history array
        # Shape: (num_iters+1, num_layers)
        num_layers = len(model)
        energy_history = jnp.zeros((num_iters + 1, num_layers))
        
        # Store initial energies at index 0
        initial_energies = jnp.array(compute_energy(model, activations, key, yy, xx, ener_fn=ener_fn, loss_fn=loss_fn, inference=inference))
        energy_history = energy_history.at[0].set(initial_energies)
        
        # Modified body function that records energies
        def body_fn_with_history(i, state):
            acts, e_hist = state
            new_acts = inference_step(acts)
            # Compute and store energies at iteration i+1
            new_energies = jnp.array(compute_energy(model, new_acts, key, yy, xx, ener_fn=ener_fn, loss_fn=loss_fn, inference=inference))
            new_e_hist = e_hist.at[i + 1].set(new_energies)
            return new_acts, new_e_hist
        
        # Run loop
        final_acts, energy_history = jax.lax.fori_loop(
            0, num_iters, body_fn_with_history, (activations, energy_history)
        )
        
        return final_acts, energy_history
    else:
        # Original fast version without history
        def body_fn(i, acts):
            return inference_step(acts)
        
        final_acts = jax.lax.fori_loop(0, num_iters, body_fn, activations)
        return final_acts, None

