def plot_energy_history(history: ArrayLike, len_model, axs = None, title1 = None, title2 = None):
# plot energy history for each layer
    if axs is None:
        fig, axs = plt.subplots(2, 1, figsize=(8, 6))
    else:
        fig = None
        
    for layer_idx in range(len_model - 1):
        axs[0].plot(history[:, layer_idx], label=f'Layer {layer_idx}')
    axs[0].set_xlabel('Iteration')
    axs[0].set_ylabel('Energy')
    axs[0].set_title(title1)
    axs[0].legend()

    for layer_idx in range(len_model):
        axs[1].plot(history[:, layer_idx], label=f'Layer {layer_idx}')
    axs[1].set_xlabel('Iteration')
    axs[1].set_ylabel('Energy')
    axs[1].set_title(title2)
    axs[1].legend()
    
    if fig is not None:
        fig.tight_layout()
        plt.show()
    else:
        return axs

