def jpc_neg_activity_grad(
        t: float | int,
        activities: PyTree[ArrayLike],
        args: Tuple[
            Tuple[PyTree[Callable], Optional[PyTree[Callable]]],
            ArrayLike,
            Optional[ArrayLike],
        ]
    ) -> PyTree[Array]:
    params, y, x  = args
    
    dFdzs = jax.grad(jpc_pc_energy_fn, argnums=1)(
        params,
        activities,
        y,
        x=x
    )
    return tree_map(lambda dFdz: -dFdz, dFdzs)

# %% ../nbs/00_core.ipynb 69
def jpc_solve_inference(
        params: Tuple[PyTree[Callable], Optional[PyTree[Callable]]],
        activities: PyTree[ArrayLike],
        output: ArrayLike,
        *,
        input: Optional[ArrayLike] = None,
        loss_id: str = "mse",
        param_type: str = "sp",
        solver: AbstractSolver = Heun(),
        max_t1: int = 20,
        dt: float | int = None,
        stepsize_controller: AbstractStepSizeController = PIDController(
            rtol=1e-3, atol=1e-3
        ),
        weight_decay: Scalar = 0.,
        spectral_penalty: Scalar = 0.,
        activity_decay: Scalar = 0.,
        record_iters: bool = False,
        record_every: int = None,
        max_steps: int = 16384
) -> PyTree[Array]:
    if record_every is not None:
        ts = jnp.arange(0, max_t1, record_every)
        saveat = SaveAt(t1=True, ts=ts)
    else:
        saveat = SaveAt(t1=True, steps=record_iters)

    solution = diffeqsolve(
        terms=ODETerm(jpc_neg_activity_grad),
        solver=solver,
        t0=0,
        t1=max_t1,
        dt0=dt,
        y0=activities,
        args=(
            params, 
            output, 
            input, 
        ),
        stepsize_controller=stepsize_controller,
        event=Event(jpc_steady_state_event_with_timeout),  # stop when returning from steady_state_event_with_timeout crosses zero
        saveat=saveat,
        max_steps=max_steps,
        throw=False  # Don't throw errors, just return what we have
    )
    return solution.ys


def jpc_steady_state_event_with_timeout(t, y, args, **kwargs):

    _atol, _rtol = 1e-3, 1e-3
    steady_state_reached = rms_norm(y) < _atol + _rtol * rms_norm(y)
    timeout_reached = jnp.array(t >= 4096, dtype=jnp.bool_)
    return jnp.logical_or(steady_state_reached, timeout_reached)

