@eqx.filter_jit
def pc_training_step(
        model: List[Callable], optimizers: List[optax.GradientTransformation],
        opt_state: List[optax.OptState], key: PRNGKeyArray, yy: ArrayLike, xx: ArrayLike = None, 
        num_inference_iters: int = 10, lr_inference: float = 0.05, ener_fn: Callable = mse_energy, loss_fn: Callable = mse_energy,
        inference_method: str = "BP", record_history = False, feedforward_init: str = "ffwd", 
        sigma: float = 0.05, random_factor: float = 1.0,
        include_input: bool = False, act_amp = None):
    # include_input = False # for supervised learning, but did not implement unsupervised yet
    inference = False # during training, we want dropout to be active
    # key, init_key, inference_key, grad_key, final_key = jax.random.split(key, 5)
    if act_amp == None:
        act_amp = [1.0 for _ in range(len(model))]

    if inference_method == "BP":
        if feedforward_init == "ffwd":
            activations = forward_and_extract_activities(model, xx, key = key, inference=inference)
        elif feedforward_init == "random":
            activations = init_activities_as_ffwd_plus_noise_real(
                key, model, xx, sigma=sigma, inference=inference, include_input=include_input, random_factor = random_factor)
        else:
            raise ValueError(f"Invalid feedforward_init: {feedforward_init}. Choose 'ffwd' or 'random'.")
        fina_acts, energy_history = perform_inference(model, [amp * act for amp, act in zip(act_amp, activations)], key, yy, xx = xx, num_iters=num_inference_iters, lr=lr_inference, record_history= record_history, ener_fn=ener_fn, loss_fn=loss_fn, inference=inference)
    elif inference_method == "ODE":
        activations = jpc_init_activities_with_ffwd(model, xx)
        ode_solution = jpc_solve_inference(
            (model, None), 
            activations, 
            yy, 
            input = xx,
            max_t1 = num_inference_iters,
            # ode slution shape: (num_layers, num_iters, batch_size, layer_dim)
            # expected final activaties shape: (num_layers, batch_size, layer_dim)
            record_every= 1 if record_history else None
        )
        fina_acts = [act[-1] for act in ode_solution]
        if record_history:
            energy_history = []
            for single_iter in range(ode_solution[0].shape[0]):
                current_act = [arr[single_iter] for arr in ode_solution]
                current_energies = compute_energy(model, current_act, key, yy, xx, ener_fn=ener_fn, loss_fn=loss_fn, inference=inference)
                energy_history.append(current_energies)
            energy_history = jnp.array(energy_history)
        else:
            energy_history = None
    else:
        raise ValueError(f"Invalid inference_method: {inference_method}. Choose 'BP' or 'ODE'.")

    def energy_fn(mdl):
        return sum(compute_energy(mdl, fina_acts, key, yy, xx, ener_fn=ener_fn, loss_fn=loss_fn, inference=inference))
    
    
    energies, grads = eqx.filter_value_and_grad(energy_fn)(model)
    
    # Create new model list with updated layers
    updated_model = []
    updated_opt_state = []
    
    for i, (layer, optimizer, grad, opt_st) in enumerate(zip(model, optimizers, grads, opt_state)):
        updates, new_opt_st = optimizer.update(grad, opt_st, eqx.filter(layer, eqx.is_array))
        new_layer = eqx.apply_updates(layer, updates)
        updated_model.append(new_layer)
        updated_opt_state.append(new_opt_st)
    
    return {
        'model': updated_model, 
        'opt_state': updated_opt_state, 
        'energies': compute_energy(model, fina_acts, key = key, y = yy, x = xx, ener_fn=ener_fn, loss_fn=loss_fn, inference=True),  # mean to set true
        'grads': grads,
        'energies_history': energy_history  
    }

