@eqx.filter_jit
def pc_final_inference_BP(
        key: PRNGKeyArray,
        model: List[Callable], yy: ArrayLike, xx: ArrayLike, 
        num_inference_iters: int = 10, lr_inference: float = 0.05, ener_fn: Callable = mse_energy, loss_fn: Callable = mse_energy,
        inference_method: str = "BP", record_history = False,
        inference: bool = True
    ) -> Dict:
    random_activities = init_activities_from_normal_ffwd(
        key, model, input_shape = xx.shape, sigma=0.05, inference=inference
    )
    if inference_method == "BP":
        fina_acts, final_energy_history = perform_inference(model, random_activities, key= key, yy=yy, xx = None, num_iters=num_inference_iters, lr=lr_inference, record_history= record_history, ener_fn=ener_fn, loss_fn=loss_fn, inference=inference)
    
    else:
        raise ValueError(f"Invalid inference_method: {inference_method}. Choose 'BP' or 'ODE'.")
    
    return{
        'activities': fina_acts,
        'energy_history': final_energy_history
    }
    
    

def pc_final_inference_ODE(
        key: PRNGKeyArray,
        model: List[Callable], y: ArrayLike, x: ArrayLike, 
        num_inference_iters: int = 10, lr_inference: float = 0.05, ener_fn: Callable = mse_energy, loss_fn: Callable = mse_energy,
        inference_method: str = "ODE", record_history = False
    ) -> Dict:
    random_activities = init_activities_from_normal_ffwd(
        key, model, input_shape = x.shape, sigma=0.05
    )

    if inference_method == "ODE":
        ode_solution = jpc_solve_inference(
            (model, None), 
            random_activities, 
            y, 
            input = None,
            max_t1 = num_inference_iters,
            # ode slution shape: (num_layers, num_iters, batch_size, layer_dim)
            # expected final activaties shape: (num_layers, batch_size, layer_dim)
            record_every= 1
        )
        fina_acts = [act[-1] for act in ode_solution]
        if record_history:
            final_energy_history = []
            for single_iter in range(ode_solution[0].shape[0]):
                current_act = [arr[single_iter] for arr in ode_solution]
                current_energies = compute_energy(model, current_act, y, None, ener_fn=ener_fn, loss_fn=loss_fn)
                final_energy_history.append(current_energies)
            final_energy_history = jnp.array(final_energy_history)
            final_energy_history = final_energy_history[~jnp.isnan(final_energy_history).all(axis=1)]
        else:
            final_energy_history = None
    else:
        raise ValueError(f"Invalid inference_method: {inference_method}. Choose 'BP' or 'ODE'.")
    
    return{
        'activities': fina_acts,
        'energy_history': final_energy_history
    }
    
    


# %% ../nbs/00_core.ipynb 91
def validate_generation(model: List[Callable], data_loader, num_inference_iters: int = 1000, lr_inference: float = 1, inference_method: str = "BP", record_history: bool = False, ener_fn:Callable = mse_energy, loss_fn:Callable = mse_energy):
    key = jax.random.PRNGKey(0)
    inference = True  # during validation, we want dropout to be disabled
    total_loss = 0.0
    # num_batches = 0
    pred_labels = []
    true_labels = []
    # pred_imgs = []
    energy_history = False
    for idx, (images, labels) in tqdm(enumerate(data_loader), total=len(data_loader), leave=False, desc="Generation Inference"):
        # Convert torch tensors to jax arrays
        x = jnp.array(labels.numpy())
        y = jnp.array(images.numpy())
        if inference_method == "BP":
            final_rst = pc_final_inference_BP(
                key, model, yy = y, xx = x,  # will be set to None inside
                num_inference_iters=num_inference_iters, lr_inference=lr_inference, inference_method=inference_method, record_history=record_history, ener_fn=ener_fn, loss_fn=loss_fn, inference=inference
            )
        elif inference_method == "ODE":
            final_rst = pc_final_inference_ODE(
                key, model, y = y, x = x,  # will be set to None inside
                num_inference_iters=num_inference_iters, lr_inference=lr_inference, inference_method=inference_method, record_history=record_history, ener_fn=ener_fn, loss_fn=loss_fn, inference=inference
            )

        # preded_imgs = final_rst['activities'][-1]
        first_act = final_rst['activities'][0].argmax(axis=-1)
        pred_labels.append(first_act)
        true_labels.append(x.argmax(axis=-1))
        if record_history == True:
            if idx == 0:
                energy_history = final_rst['energy_history']
            else:
                energy_history += final_rst['energy_history']
    # just select first 16 images to visualize
    
    model_output = one_step_forward(model, x, key = key, inference=inference)[:16].reshape(16, 1, 28, 28)
    fig, axs = plt.subplots(4, 4, figsize=(6, 6))
    for i, ax in enumerate(axs.flatten()):
        ax.imshow(model_output[i].squeeze(), cmap='gray')
        ax.set_title(f'{x[i].argmax()}')
        ax.axis('off')
    fig.tight_layout()
    plt.show()

    if record_history ==True:
        energy_history = energy_history / len(data_loader)
        plot_energy_history(energy_history, len(model), axs=None,
            title1 = 'Generation Inference Energy History',
            title2 = 'Generation Inference Energy History'
            )
    pred_labels = jnp.concatenate(pred_labels)
    true_labels = jnp.concatenate(true_labels)
    acc = jnp.mean(pred_labels == true_labels)
    print(f'Generation Accuracy: {acc:.4f}')
